package com.leixu.huiliao;
import android.app.Activity; import android.os.Bundle; import android.webkit.*; import android.widget.Toast; import android.content.ContentValues; import android.net.Uri; import android.os.Build; import android.provider.MediaStore; import android.util.Base64; import java.io.OutputStream;
public class MainActivity extends Activity {
 private WebView webView;
 @Override public void onCreate(Bundle state){ super.onCreate(state); getWindow().setStatusBarColor(android.graphics.Color.rgb(247,247,251)); getWindow().setNavigationBarColor(android.graphics.Color.rgb(247,247,251)); if(Build.VERSION.SDK_INT>=23)getWindow().getDecorView().setSystemUiVisibility( android.view.View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR | android.view.View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR); webView=new WebView(this); WebSettings s=webView.getSettings(); s.setJavaScriptEnabled(true); s.setDomStorageEnabled(true); s.setDatabaseEnabled(true); s.setAllowFileAccess(true); webView.setWebChromeClient(new WebChromeClient()); webView.addJavascriptInterface(new AndroidBridge(),"AndroidBridge"); setContentView(webView); webView.loadUrl("file:///android_asset/index.html"); }
 public class AndroidBridge { @JavascriptInterface public void saveBase64(String data,String name,String mime){ runOnUiThread(()->{ try { byte[] bytes=Base64.decode(data,Base64.DEFAULT); ContentValues v=new ContentValues(); v.put(MediaStore.Downloads.DISPLAY_NAME,name); v.put(MediaStore.Downloads.MIME_TYPE,mime); if(Build.VERSION.SDK_INT>=29)v.put(MediaStore.Downloads.RELATIVE_PATH,"Download"); Uri u=getContentResolver().insert(MediaStore.Downloads.EXTERNAL_CONTENT_URI,v); if(u==null)throw new Exception("无法创建下载文件"); try(OutputStream out=getContentResolver().openOutputStream(u)){if(out==null)throw new Exception("无法写入文件");out.write(bytes);} Toast.makeText(MainActivity.this,"已保存到下载目录："+name,Toast.LENGTH_LONG).show(); }catch(Exception e){Toast.makeText(MainActivity.this,"导出失败："+e.getMessage(),Toast.LENGTH_LONG).show();} }); } }
 @Override public void onBackPressed(){if(webView!=null&&webView.canGoBack())webView.goBack();else super.onBackPressed();}
 @Override protected void onDestroy(){if(webView!=null){webView.destroy();webView=null;}super.onDestroy();}
}
